pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1, "", ""); }
    function testRegression_property() public {
        c.mintToken(address(this), 9);
        bool ok;
        try c.burn(10) { ok = true; } catch { ok = false; }
        assertTrue(ok == true, "burn should succeed");
        assertTrue(c.totalSupply() == 0, "totalSupply after burn");
    }
}
